/// `Arc<Mutex<..>>` rather than `Rc<RefCell<..>>`.
///
/// Every host closure captures this handle, so it inherits whatever bound
/// `HostFunction::from` imposes — and the interpreter in `wasm-runtime` requires
/// `Send + Sync` because a paged run is held across an `await` in
/// `FerriteApp::run`. `Rc` and `RefCell` are neither.
pub type ShimRef = Arc<Mutex<Shim>>;

/// Lock the shim.
