/// `pub(crate)` because `engine.rs` holds the same handle: a second, private
/// copy of this could disagree about poisoning, and a run that panicked inside a
/// host closure would then behave differently depending on which side noticed.
///
/// Poisoning can only follow a panic inside a host closure, and that already
/// aborts the whole run — so recovering the guard is the honest choice over a
/// second panic raised on the way out of the first.
pub(crate) fn lock(s: &ShimRef) -> std::sync::MutexGuard<'_, Shim> {
    s.lock().unwrap_or_else(|e| e.into_inner())
}

fn mem_write(ctx: &mut FuncContext<'_>, offset: usize, bytes: &[u8]) -> RtResult<()> {
    let mem = ctx.memory("memory")?;
    mem.copy_from_slice(ctx.store_mut(), offset, bytes)?;
    Ok(())
}

fn mem_read(ctx: &mut FuncContext<'_>, offset: usize, len: usize) -> RtResult<Vec<u8>> {
    let mem = ctx.memory("memory")?;
    mem.read_vec(ctx.store(), offset, len)
}

fn w32(ctx: &mut FuncContext<'_>, offset: i32, v: u32) -> RtResult<()> {
    mem_write(ctx, offset as usize, &v.to_le_bytes())
}

fn w64(ctx: &mut FuncContext<'_>, offset: i32, v: u64) -> RtResult<()> {
    mem_write(ctx, offset as usize, &v.to_le_bytes())
}

/// Count complete request frames currently in the stdout buffer.
pub fn count_request_frames(stdout: &[u8]) -> usize {
    let s = String::from_utf8_lossy(stdout);
    let mut count = 0;
    let mut rest = s.as_ref();
    while let Some(i) = rest.find(FRAME) {
        let after = &rest[i + FRAME.len()..];
        if let Some(nl) = after.find('\n') {
            // Only count request frames (op present), not the final output frame.
            let line = &after[..nl];
            if line.contains("\"op\"") {
                count += 1;
            }
            rest = &after[nl + 1..];
        } else {
            break;
        }
    }
    count
}

